"""模型无关 Agentic RAG：规划、分层检索、图扩展、停止与证据包。"""

import os
import re
import sys
import json
import argparse

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import kb_lib as K

SCHEMA_VERSION = "kb.agentic.v1"
COMPLEX_RE = re.compile(
    r"对比|比较|机制|为什么|争议|差异|趋势|多跳|关联|证据|综述|评估|核对|原文|出处|"
    r"compare|comparison|why|mechanism|controvers|evidence|trend|versus|\bvs\b", re.I)
SIMPLE_RE = re.compile(r"是什么|定义|别名|哪个|谁|多少|数值|列表|列出|what is|define|list", re.I)


def classify_query(query):
    q = query.strip()
    complex_hits = COMPLEX_RE.findall(q)
    clauses = [x for x in re.split(r"[，。；;？?！!\n]+", q) if x.strip()]
    if complex_hits or len(clauses) > 1 or len(q) > 48:
        reasons = []
        if complex_hits:
            reasons.append("含综合/比较/核验意图")
        if len(clauses) > 1:
            reasons.append("包含多个子问题")
        if len(q) > 48:
            reasons.append("查询较长，需控制检索深度")
        return {"strategy": "agentic", "reasons": reasons}
    return {"strategy": "simple",
            "reasons": ["短查询且未出现综合意图" if not SIMPLE_RE.search(q)
                        else "事实/定义型查询"]}


def _split_query(query, max_subqueries):
    parts = [x.strip() for x in re.split(r"[，。；;？?！!\n]+", query) if x.strip()]
    if len(parts) == 1:
        m = re.split(r"\s+(?:vs\.?|versus)\s+", query, flags=re.I)
        if len(m) > 1:
            parts = [x.strip() for x in m if x.strip()]
    out = [query]
    for part in parts:
        if part != query and len(part) >= 2 and part not in out:
            out.append(part)
    return out[:max_subqueries]


def load_plan(path, query, max_subqueries=5):
    if not path:
        return {"planner": "deterministic", "subqueries": _split_query(query, max_subqueries)}
    with open(path, encoding="utf-8") as f:
        obj = json.load(f)
    if not isinstance(obj, dict):
        raise ValueError("plan 顶层必须是 JSON 对象，例如 "
                         "{\"subqueries\": [\"...\"], \"reason\": \"...\"}")
    subqueries = obj.get("subqueries")
    if not isinstance(subqueries, list) or not subqueries:
        raise ValueError("plan.subqueries 必须是非空字符串数组")
    if not all(isinstance(x, str) and x.strip() for x in subqueries):
        raise ValueError("plan.subqueries 必须全部是非空字符串")
    if len(subqueries) > max_subqueries:
        raise ValueError(f"子查询超过上限 {max_subqueries}")
    return {"planner": "external-json", "subqueries": [x.strip() for x in subqueries],
            "reason": str(obj.get("reason") or "")[:500]}


def _key(item, layer):
    if layer == "L3":
        return (layer, item.get("path"), item.get("line_start"), item.get("line_end"))
    return (layer, item.get("path") or item.get("name"))


def _merge_evidence(target, seen, package, subquery):
    added = 0
    for layer in ("L1", "L2", "L3"):
        for item in package.get(layer) or []:
            key = _key(item, layer)
            row = dict(item, supporting_queries=[subquery])
            if key in seen:
                old = target[seen[key]]
                if subquery not in old["supporting_queries"]:
                    old["supporting_queries"].append(subquery)
                continue
            seen[key] = len(target)
            target.append(row)
            added += 1
    return added


def _graph_frontier(evidence, limit=2):
    import kb_graph as G
    if not os.path.exists(G.FULL):
        return []
    pages, out_adj, in_adj = G.load_graph()
    seeds = [x.get("name") for x in evidence
             if x.get("layer") in ("L1", "L2") and x.get("name") in pages]
    known = {x.get("name") for x in evidence}
    frontier = []
    for seed in seeds[:3]:
        neighbors = set(out_adj.get(seed, ())) | set(in_adj.get(seed, ()))
        for name in sorted(neighbors):
            if name not in known and name not in frontier:
                frontier.append(name)
    return frontier[:limit]


def run(query, plan_path=None, max_steps=6, budget=None, graph_expansion=True):
    import kb_route as R
    decision = classify_query(query)
    plan = load_plan(plan_path, query)
    budget = dict(R.DEFAULT_BUDGET, **(budget or {}))
    evidence = []
    seen = {}
    steps = []
    warnings = []

    for subquery in plan["subqueries"]:
        if len(steps) >= max_steps:
            break
        pkg = R.route(subquery, budget=budget, layers=(1, 2, 3))
        added = _merge_evidence(evidence, seen, pkg, subquery)
        steps.append({"kind": "retrieve", "query": subquery, "new_evidence": added,
                      "counts": pkg.get("counts"), "signal": pkg.get("signal")})

    if graph_expansion and len(steps) < max_steps:
        for name in _graph_frontier(evidence):
            if len(steps) >= max_steps:
                break
            pkg = R.route(name, budget={"L1": 2, "L2": 2, "L3": 0}, layers=(1, 2))
            added = _merge_evidence(evidence, seen, pkg, name)
            steps.append({"kind": "graph-expand", "query": name, "new_evidence": added,
                          "counts": pkg.get("counts"), "signal": pkg.get("signal")})
            if added == 0:
                break

    counts = {layer: sum(1 for x in evidence if x.get("layer") == layer)
              for layer in ("L1", "L2", "L3")}
    gaps = []
    if not counts["L2"]:
        gaps.append("没有文献卡证据，不能形成有来源支撑的综合结论")
    if not counts["L3"]:
        gaps.append("没有原文块证据，需补充原文核验")
    weak = [s for s in steps if (s.get("signal") or {}).get("low_confidence")]
    if weak:
        warnings.append(f"{len(weak)} 个子查询低置信，应视为可能的知识空白")
    if len(steps) >= max_steps and len(plan["subqueries"]) > len(steps):
        gaps.append("达到步骤预算，仍有子查询未执行")

    result = {
        "schema_version": SCHEMA_VERSION,
        "ok": True,
        "status": "partial" if gaps else "ready_for_synthesis",
        "strategy": "agentic",
        "query": query,
        "classification": decision,
        "plan": plan,
        "steps": steps,
        "evidence": evidence,
        "counts": counts,
        "gaps": gaps,
        "warnings": warnings,
        "stop": {"max_steps": max_steps, "executed_steps": len(steps),
                 "reason": "budget" if len(steps) >= max_steps else "frontier_exhausted"},
    }
    result["synthesis_request"] = {
        "schema_version": "kb.synthesis-request.v1",
        "query": query,
        "instructions": [
            "仅依据 evidence 作答，不得补写库外事实。",
            "L1 是本库综合，L2 是单篇主张，L3 是原文字面证据，不得混同。",
            "每个关键结论附 path 与行号（若有），单源或分歧必须显式标注。",
            "gaps 非空时必须说明证据不足，不得宣称完整回答。",
        ],
        "evidence": evidence,
        "gaps": gaps,
    }
    return result


def selftest():
    ok = fail = 0

    def chk(label, condition):
        nonlocal ok, fail
        ok += bool(condition)
        fail += not bool(condition)
        print(f"  [{'ok' if condition else 'FAIL'}] {label}")

    chk("定义问题走 simple", classify_query("什么是固态电解质")["strategy"] == "simple")
    chk("比较问题走 agentic", classify_query("比较两类电解质的机制差异")["strategy"] == "agentic")
    chk("多子问题走 agentic", classify_query("定义界面阻抗；列出影响因素")["strategy"] == "agentic")
    chk("确定性规划保留原问题", load_plan(None, "比较 A 与 B")["subqueries"][0] == "比较 A 与 B")
    chk("查询分解有上限", len(load_plan(None, "a；b；c；d；e；f；g", 5)["subqueries"]) <= 5)
    print(f"SELFTEST {'PASSED' if not fail else 'FAILED'}: {ok}/{ok + fail}")
    return 0 if not fail else 1


def main():
    ap = argparse.ArgumentParser(description="模型无关 Agentic RAG")
    ap.add_argument("query", nargs="?", default="")
    ap.add_argument("--plan", default="", help="外部 LLM 规划 JSON")
    ap.add_argument("--max-steps", type=int, default=6)
    ap.add_argument("--budget", default="", help="L1,L2,L3，如 4,5,6")
    ap.add_argument("--no-graph", action="store_true")
    ap.add_argument("--json", action="store_true")
    ap.add_argument("--selftest", action="store_true")
    args = ap.parse_args()
    if args.selftest:
        return selftest()
    if not args.query:
        ap.error("query 不能为空（--selftest 除外）")
    try:
        data = run(args.query, plan_path=args.plan or None, max_steps=args.max_steps,
                   budget=K.parse_budget(args.budget), graph_expansion=not args.no_graph)
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        print(K.json_dumps({"schema_version": SCHEMA_VERSION, "ok": False,
                          "error": str(exc)}, ensure_ascii=False), file=sys.stderr)
        return 2
    print(K.json_dumps(data, ensure_ascii=False, indent=1))
    return 0 if data["ok"] else 1


if __name__ == "__main__":
    K.console_encoding()
    sys.exit(main())
